// src/utils/tokenCounter.ts
function countTokens(text) {
  return Math.ceil(text.length / 4);
}
function countMessageTokens(message) {
  let tokens = 0;
  if (typeof message.content === "string") {
    tokens += countTokens(message.content);
  } else if (Array.isArray(message.content)) {
    for (const part of message.content) {
      if (part.type === "text") {
        tokens += countTokens(part.text);
      } else if (part.type === "tool-result") {
        const resultContent = typeof part.result?.llmContent === "string" ? part.result.llmContent : JSON.stringify(part.result?.llmContent || "");
        tokens += countTokens(resultContent);
      }
    }
  }
  return tokens;
}
function countTotalTokens(messages) {
  return messages.reduce((total, msg) => total + countMessageTokens(msg), 0);
}
var init_tokenCounter = __esm({
  "src/utils/tokenCounter.ts"() {
    init_esm_shims();
  }
});

