async function runFirstTimeSetup() {
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
  });
  console.log("\u8BF7\u9009\u62E9 AI \u63D0\u4F9B\u5546:");
  console.log("  1. OpenAI (GPT-4, GPT-3.5)");
  console.log("  2. Anthropic (Claude)");
  console.log("  3. DeepSeek (\u56FD\u5185\u53EF\u7528\uFF0C\u6027\u4EF7\u6BD4\u9AD8)");
  console.log("  4. GLM (\u667A\u8C31\uFF0COpenAI \u517C\u5BB9)");
  console.log("  5. OpenRouter (\u591A\u6A21\u578B\u805A\u5408)");
  console.log("  6. \u81EA\u5B9A\u4E49 (OpenAI \u517C\u5BB9 API)");
  console.log("");
  const choice = await question(rl, "\u8BF7\u8F93\u5165\u9009\u9879 (1-6): ");
  const providerKey = getProviderKey(choice.trim());
  console.log("");
  const apiKey = await question(rl, "\u8BF7\u8F93\u5165 API Key: ");
  console.log("");
  let baseURL;
  if (providerKey === "custom") {
    baseURL = await question(rl, "\u8BF7\u8F93\u5165 API Base URL (\u4F8B\u5982: https://api.example.com/v1): ");
    console.log("");
  }
  const defaultModel = PROVIDERS2[providerKey].defaultModel;
  const modelInput = await question(rl, `\u8BF7\u8F93\u5165\u6A21\u578B\u540D\u79F0 (\u76F4\u63A5\u56DE\u8F66\u4F7F\u7528\u9ED8\u8BA4: ${defaultModel}): `);
  const model = modelInput.trim() || defaultModel;
  rl.close();
  createDefaultConfig(apiKey.trim(), providerKey, model, baseURL || PROVIDERS2[providerKey].baseURL);
  console.log("");
  console.log("\u2705 \u914D\u7F6E\u5DF2\u4FDD\u5B58\u5230: ~/.codemate/config.json");
  console.log("");
  console.log(`\u63D0\u4F9B\u5546: ${PROVIDERS2[providerKey].name}`);
  console.log(`\u6A21\u578B: ${model}`);
  if (baseURL || PROVIDERS2[providerKey].baseURL) {
    console.log(`Base URL: ${baseURL || PROVIDERS2[providerKey].baseURL}`);
  }
}
function getProviderKey(choice) {
  switch (choice) {
    case "1":
      return "openai";
    case "2":
      return "anthropic";
    case "3":
      return "deepseek";
    case "4":
      return "glm";
    case "5":
      return "openrouter";
    case "6":
      return "custom";
    default:
      return "openai";
  }
}
function question(rl, query) {
  return new Promise((resolve22) => {
    rl.question(query, resolve22);
  });
}

